insert into public.curated_courses (id, slug, title, description)
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('b98462b1-1f6b-42c1-b23f-aac1d062a1cf', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'The American Legal System and Hospitality Decision-Making', 'Hospitality managers operate where federal, state, tribal, territorial, and local rules overlap. This section builds the legal literacy needed to recognize an issue, find controlling authority, preserve facts, and involve qualified counsel before an operational problem becomes a claim.', 0),
  ('8271beca-2277-405d-ad50-d23c9f858981', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b98462b1-1f6b-42c1-b23f-aac1d062a1cf', 'subtopic'::public.curated_course_node_type, 'Sources and hierarchy of law', 'Students learn which legal authority controls, how conflicts are resolved, and why an online summary is not a substitute for current primary law.', 0),
  ('ea686003-2054-4448-aa5e-66726fda3139', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8271beca-2277-405d-ad50-d23c9f858981', 'concept'::public.curated_course_node_type, 'U.S. Constitution; federal and state constitutions', null, 0),
  ('bf84affe-a4ec-463c-be28-dd488d45b328', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8271beca-2277-405d-ad50-d23c9f858981', 'concept'::public.curated_course_node_type, 'Statutes, regulations, ordinances, administrative guidance, and licensing conditions', null, 1),
  ('179f3391-803a-43fe-8c09-63e7b2217154', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8271beca-2277-405d-ad50-d23c9f858981', 'concept'::public.curated_course_node_type, 'Federal and state judicial opinions; binding precedent versus persuasive authority', null, 2),
  ('15e233d9-2de9-4c36-998b-5c513307203d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b98462b1-1f6b-42c1-b23f-aac1d062a1cf', 'subtopic'::public.curated_course_node_type, 'Courts, agencies, jurisdiction, and procedure', 'This subtopic maps the institutions that create, enforce, and interpret hospitality obligations.', 1),
  ('539fa714-b222-47b8-a211-657ad8ea9618', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15e233d9-2de9-4c36-998b-5c513307203d', 'concept'::public.curated_course_node_type, 'Federal and state trial and appellate courts; subject-matter and personal jurisdiction', null, 0),
  ('52a766fa-c3bd-4438-81b0-f84d857e0c84', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15e233d9-2de9-4c36-998b-5c513307203d', 'concept'::public.curated_course_node_type, 'Administrative agencies, investigations, inspections, hearings, penalties, and judicial review', null, 1),
  ('bf51ed3b-8e9d-4f98-92d8-cc89d327f7f3', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15e233d9-2de9-4c36-998b-5c513307203d', 'concept'::public.curated_course_node_type, 'Pleadings, discovery, motions, trial, appeals, burdens of proof, remedies, and limitation periods', null, 2),
  ('6f3a04b4-5897-45f3-b85f-fecedeb1274c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b98462b1-1f6b-42c1-b23f-aac1d062a1cf', 'subtopic'::public.curated_course_node_type, 'Managerial issue spotting and escalation', 'Students practice turning an operational story into legally relevant facts, questions, evidence, and decisions without pretending to provide legal advice.', 2),
  ('56b37582-e457-4a1f-92c6-5af700152070', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '6f3a04b4-5897-45f3-b85f-fecedeb1274c', 'concept'::public.curated_course_node_type, 'Parties, duties, conduct, causation, injury, defenses, damages, and available remedies', null, 0),
  ('bbe599f0-b38e-4486-851b-371d325e0c04', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '6f3a04b4-5897-45f3-b85f-fecedeb1274c', 'concept'::public.curated_course_node_type, 'Privilege, litigation holds, records preservation, incident reports, and communications discipline', null, 1),
  ('42fd5f2b-5e58-4159-914d-a846f8e9249e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '6f3a04b4-5897-45f3-b85f-fecedeb1274c', 'concept'::public.curated_course_node_type, 'Counsel referral, insurer notice, regulator response, expert consultation, and decision documentation', null, 2),
  ('30bfa9b3-db9e-423b-a01d-e489ee9267c1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Contracts, Agency, and Commercial Commitments', 'Hospitality operations are built on promises to guests, groups, suppliers, owners, brands, platforms, and employees. Students learn how agreements form, who may bind the enterprise, and how contract language allocates operational and financial risk.', 1),
  ('8c73ef71-a2ab-4d9c-ad3e-4ada85ea46ad', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '30bfa9b3-db9e-423b-a01d-e489ee9267c1', 'subtopic'::public.curated_course_node_type, 'Formation, interpretation, and enforceability', 'Students learn the elements of a contract and the recurring defects that make an apparent promise uncertain or unenforceable.', 0),
  ('c280d2e8-48fe-4007-85f3-18c12d4742f0', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8c73ef71-a2ab-4d9c-ad3e-4ada85ea46ad', 'concept'::public.curated_course_node_type, 'Offer, acceptance, consideration, mutual assent, capacity, legality, and definite terms', null, 0),
  ('c5064a15-8c29-4c99-84a4-a0c3cc534048', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8c73ef71-a2ab-4d9c-ad3e-4ada85ea46ad', 'concept'::public.curated_course_node_type, 'Written, oral, electronic, clickwrap, course-of-dealing, and implied agreements', null, 1),
  ('bbc61f6a-a34b-447e-8da8-4857c23a9b13', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8c73ef71-a2ab-4d9c-ad3e-4ada85ea46ad', 'concept'::public.curated_course_node_type, 'Statute of Frauds, parol evidence, ambiguity, modification, waiver, severability, and electronic signatures', null, 2),
  ('8715bfad-d1fe-46f6-920d-bf8c0288232e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '30bfa9b3-db9e-423b-a01d-e489ee9267c1', 'subtopic'::public.curated_course_node_type, 'Performance, breach, defenses, and remedies', 'This subtopic connects contract doctrine to cancellations, service failures, payment disputes, and disrupted events.', 1),
  ('1f6e43e6-73ad-4a49-a6d0-434a24236f34', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8715bfad-d1fe-46f6-920d-bf8c0288232e', 'concept'::public.curated_course_node_type, 'Conditions, covenants, representations, warranties, standards, milestones, and acceptance', null, 0),
  ('c3cf1b13-33f2-4df9-8cac-f458ff54ad75', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8715bfad-d1fe-46f6-920d-bf8c0288232e', 'concept'::public.curated_course_node_type, 'Material breach, anticipatory repudiation, impossibility, impracticability, frustration, mistake, duress, and unconscionability', null, 1),
  ('752950be-af47-454b-9b23-87935d64eb09', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8715bfad-d1fe-46f6-920d-bf8c0288232e', 'concept'::public.curated_course_node_type, 'Expectation, reliance, restitution, liquidated damages, mitigation, specific performance, termination, and cure', null, 2),
  ('9dbf02b0-124d-49f6-bae6-20ae3ecf86cf', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '30bfa9b3-db9e-423b-a01d-e489ee9267c1', 'subtopic'::public.curated_course_node_type, 'Agency and authority', 'Students examine when employees, managers, agents, travel sellers, and platforms create obligations for another party.', 2),
  ('1e3b99e3-7830-4c2c-9c89-6e3abca49e76', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9dbf02b0-124d-49f6-bae6-20ae3ecf86cf', 'concept'::public.curated_course_node_type, 'Actual, implied, apparent, and ratified authority', null, 0),
  ('41798752-1f2e-4c27-ad2f-cc4bf4bf09ff', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9dbf02b0-124d-49f6-bae6-20ae3ecf86cf', 'concept'::public.curated_course_node_type, 'Principal and agent duties; disclosed, partially disclosed, and undisclosed principals', null, 1),
  ('851d055e-0e6e-4666-afcf-a61d5aae1ca1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9dbf02b0-124d-49f6-bae6-20ae3ecf86cf', 'concept'::public.curated_course_node_type, 'Vicarious liability, independent contractors, scope of employment, and authority controls', null, 2),
  ('b3d97d1f-13a6-4591-b075-f89afc76f5cd', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Innkeeper–Guest Relationship, Reservations, and Guest Property', 'Lodging law combines common-law duties, state innkeeper statutes, contracts, civil-rights rules, and consumer protections. Students learn how legal status changes from inquiry and reservation through occupancy, removal, departure, and lost-property handling.', 2),
  ('bbcc3975-a826-4075-846f-d65342aeebde', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b3d97d1f-13a6-4591-b075-f89afc76f5cd', 'subtopic'::public.curated_course_node_type, 'Admission, reservations, rates, and nondiscrimination', 'Students evaluate when a lodging operator may refuse service, what reservation promises mean, and how published terms must align with public-accommodation duties.', 0),
  ('003fdbbd-d338-4acb-bda0-fe4942c8cbca', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bbcc3975-a826-4075-846f-d65342aeebde', 'concept'::public.curated_course_node_type, 'Guest status, right to exclude, lawful refusal, protected classes, and neutral conduct rules', null, 0),
  ('7d0841d6-ec67-4e7d-93e2-40be19de67f5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bbcc3975-a826-4075-846f-d65342aeebde', 'concept'::public.curated_course_node_type, 'Reservation confirmation, deposits, guarantees, cancellations, no-shows, overbooking, and walking guests', null, 1),
  ('2f697650-428c-4794-8516-452b767f71af', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bbcc3975-a826-4075-846f-d65342aeebde', 'concept'::public.curated_course_node_type, 'Rate disclosure, mandatory fees, taxes, authorization holds, refunds, and records', null, 2),
  ('a9ba849a-4acb-4b18-aac1-c537604e74e4', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b3d97d1f-13a6-4591-b075-f89afc76f5cd', 'subtopic'::public.curated_course_node_type, 'Occupancy, privacy, access, and removal', 'This subtopic addresses the guest''s possessory and privacy interests and the operator''s safety and property-management responsibilities.', 1),
  ('b9e49176-2c83-4ae3-ad9a-4e5555d53d07', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a9ba849a-4acb-4b18-aac1-c537604e74e4', 'concept'::public.curated_course_node_type, 'Guest privacy, room entry, housekeeping, maintenance, emergencies, warrants, subpoenas, and law-enforcement requests', null, 0),
  ('ed8a237c-21ec-4cc6-8c3c-702017735acd', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a9ba849a-4acb-4b18-aac1-c537604e74e4', 'concept'::public.curated_course_node_type, 'Distinguishing guest, tenant, licensee, trespasser, and long-term occupant under state law', null, 1),
  ('ad108c33-bffd-411d-a6ab-8f2d6bc4c2c5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a9ba849a-4acb-4b18-aac1-c537604e74e4', 'concept'::public.curated_course_node_type, 'Eviction or ejection, breach of peace, abandoned rooms, safe procedures, and counsel/law-enforcement escalation', null, 2),
  ('97e8175d-2180-4ae0-a605-5dd40cedc17b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b3d97d1f-13a6-4591-b075-f89afc76f5cd', 'subtopic'::public.curated_course_node_type, 'Bailment, safekeeping, lost property, and statutory limits', 'Students learn how custody and notice affect responsibility for luggage, vehicles, valuables, and property left behind.', 2),
  ('25d8fba6-aca0-4848-aa72-c425fa9257e2', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '97e8175d-2180-4ae0-a605-5dd40cedc17b', 'concept'::public.curated_course_node_type, 'Bailment formation, standard of care, proof, defenses, and damages', null, 0),
  ('68bc96a6-55ca-4413-ba07-8cee8282682b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '97e8175d-2180-4ae0-a605-5dd40cedc17b', 'concept'::public.curated_course_node_type, 'Innkeeper statutes, safe-deposit procedures, posted notices, parking disclaimers, and limits of liability', null, 1),
  ('7e7d9747-f7d6-4275-be3b-7cdf4c50075d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '97e8175d-2180-4ae0-a605-5dd40cedc17b', 'concept'::public.curated_course_node_type, 'Lost-and-found chain of custody, retention, disposal, employee property, and evidence preservation', null, 2),
  ('43eaa9a2-8b47-4561-97ff-16ec3e99d148', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Torts, Negligence, and Premises Liability', 'Hospitality businesses invite the public into spaces containing foreseeable service, crowd, pool, elevator, food, alcohol, and security risks. This section teaches a disciplined negligence analysis and the operational evidence needed to prevent or defend claims.', 3);
