values
  ('c0bd69e1-ddcb-4184-9db3-630151d0d647', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '43eaa9a2-8b47-4561-97ff-16ec3e99d148', 'subtopic'::public.curated_course_node_type, 'Intentional torts and business responsibility', 'Students distinguish intentional conduct from negligence and identify when an employer may be liable for employee or security actions.', 0),
  ('a4355494-5ba7-4da4-8c59-3e12880d7378', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'c0bd69e1-ddcb-4184-9db3-630151d0d647', 'concept'::public.curated_course_node_type, 'Assault, battery, false imprisonment, trespass, conversion, defamation, privacy torts, and intentional infliction', null, 0),
