  ('9929109c-b569-4c37-a856-b60b111b6aed', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'c0bd69e1-ddcb-4184-9db3-630151d0d647', 'concept'::public.curated_course_node_type, 'Respondeat superior, negligent hiring/supervision/retention, ratification, and punitive damages', null, 2),
  ('d9f2dae7-b1f9-44c9-ba0c-d1e809e8301e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '43eaa9a2-8b47-4561-97ff-16ec3e99d148', 'subtopic'::public.curated_course_node_type, 'Negligence framework', 'This subtopic builds the core method for analyzing duty, breach, causation, injury, and defenses.', 1),
  ('ca09139e-9463-4055-9830-019f578724d2', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd9f2dae7-b1f9-44c9-ba0c-d1e809e8301e', 'concept'::public.curated_course_node_type, 'Reasonable care, industry custom, statutes and negligence per se, professional standards, and foreseeable plaintiffs', null, 0),
  ('76264dae-edd6-44d5-bf6b-599a6791949a', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd9f2dae7-b1f9-44c9-ba0c-d1e809e8301e', 'concept'::public.curated_course_node_type, 'Actual and proximate causation, intervening acts, multiple causes, and proof', null, 1),
  ('fb958941-89c9-43b5-97bb-676e0cf07e07', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd9f2dae7-b1f9-44c9-ba0c-d1e809e8301e', 'concept'::public.curated_course_node_type, 'Compensatory damages, comparative or contributory fault, assumption of risk, waivers, and indemnity', null, 2),
  ('8f7062f8-37af-46ca-b6f6-be7283c62c4c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '43eaa9a2-8b47-4561-97ff-16ec3e99d148', 'subtopic'::public.curated_course_node_type, 'Premises, products, and third-party acts', 'Students apply negligence doctrine to physical conditions, products, vendors, criminal acts, and changing property use.', 2),
  ('3458fbd1-a2da-49f9-bdae-b0707052b27e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f7062f8-37af-46ca-b6f6-be7283c62c4c', 'concept'::public.curated_course_node_type, 'Inspection, notice, maintenance, warnings, lighting, flooring, stairs, balconies, pools, spas, elevators, and parking', null, 0),
  ('0caf9b94-fa4a-40c2-88e1-a44712727685', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f7062f8-37af-46ca-b6f6-be7283c62c4c', 'concept'::public.curated_course_node_type, 'Invitees, licensees, trespassers, children, recreational activities, and jurisdictional variations', null, 1),
  ('c3d8bc19-9d40-4783-a505-2fb8b979c8cc', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f7062f8-37af-46ca-b6f6-be7283c62c4c', 'concept'::public.curated_course_node_type, 'Foreseeable crime, security plans, keys and locks, vendors, products liability, recalls, and evidence', null, 2),
  ('e93a57c0-6677-47e0-bf8a-cfbb5f8b24a2', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Safety, Security, Emergencies, and Public-Health Duties', 'Hospitality managers must make rapid decisions during fires, severe weather, violence, medical events, outbreaks, evacuations, and technology outages. This section connects duty of care to preparedness, response, continuity, documentation, and respectful communication.', 4),
  ('15ed900b-8310-4670-9c5a-3b315b6f64a0', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'e93a57c0-6677-47e0-bf8a-cfbb5f8b24a2', 'subtopic'::public.curated_course_node_type, 'Emergency planning and duty of care', 'Students learn to design a proportionate all-hazards program and understand that plans must align with local codes and public-safety authorities.', 0),
  ('35767f7c-1d81-4bde-9a36-27f5be4c30ad', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15ed900b-8310-4670-9c5a-3b315b6f64a0', 'concept'::public.curated_course_node_type, 'Hazard assessment, emergency action plans, evacuation, shelter, accountability, reunification, and continuity', null, 0),
  ('d8b5b3b2-ccae-4f66-b52f-58d84f58c6e6', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15ed900b-8310-4670-9c5a-3b315b6f64a0', 'concept'::public.curated_course_node_type, 'Fire and life safety, occupancy, alarms, suppression, exits, crowd management, pools, and transportation', null, 1),
  ('18765760-88f7-41dd-9ece-ed30f4c0c667', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '15ed900b-8310-4670-9c5a-3b315b6f64a0', 'concept'::public.curated_course_node_type, 'Emergency roles, incident command, drills, mutual aid, contractors, and accessible communications', null, 2),
  ('f2c2577b-a6f5-4c7b-8c7b-7362d75ee247', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'e93a57c0-6677-47e0-bf8a-cfbb5f8b24a2', 'subtopic'::public.curated_course_node_type, 'Security, violence, and safeguarding', 'This subtopic examines reasonable protective measures without assuming that every adverse event is preventable.', 1),
  ('87b83b39-1d91-42fe-baac-e450846d5cf8', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'f2c2577b-a6f5-4c7b-8c7b-7362d75ee247', 'concept'::public.curated_course_node_type, 'Threat assessment, access control, keys, surveillance, patrol, cash, cyber-physical security, and suspicious activity', null, 0),
  ('b1aeaec7-2585-48c9-9dec-6234b0c7bd0c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'f2c2577b-a6f5-4c7b-8c7b-7362d75ee247', 'concept'::public.curated_course_node_type, 'Workplace violence, trafficking indicators, vulnerable guests, minors, harassment, and escalation protocols', null, 1),
  ('48c9ffbb-0b14-4a26-87c2-1ef088b6558f', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'f2c2577b-a6f5-4c7b-8c7b-7362d75ee247', 'concept'::public.curated_course_node_type, 'Security contractors, off-duty police, use of force, privacy, records, and post-incident care', null, 2),
  ('8f08e384-780b-4ebf-9750-c904d00e73fe', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'e93a57c0-6677-47e0-bf8a-cfbb5f8b24a2', 'subtopic'::public.curated_course_node_type, 'Medical events, outbreaks, and government orders', 'Students practice coordinating guest care, employee safety, operations, privacy, and agency direction during health events.', 2),
  ('0ac77327-46fd-4889-92c2-4815a7426dda', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f08e384-780b-4ebf-9750-c904d00e73fe', 'concept'::public.curated_course_node_type, 'First aid/AED programs, emergency medical services, Good Samaritan variation, and documentation', null, 0),
  ('c7723342-afbb-4dcc-a2a0-27056b479317', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f08e384-780b-4ebf-9750-c904d00e73fe', 'concept'::public.curated_course_node_type, 'Communicable disease, exposure, isolation, sanitation, closures, public-health orders, and worker protections', null, 1),
  ('b9ca7d8a-affc-4c43-98b8-200bfdb0708b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '8f08e384-780b-4ebf-9750-c904d00e73fe', 'concept'::public.curated_course_node_type, 'Americans with Disabilities Act issues, confidentiality, rumor control, media response, and recovery', null, 2),
  ('3fa82243-5fa0-462c-a233-bb1fbfa95326', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Food Safety, Allergens, and Alcohol Regulation', 'Restaurants, bars, banquets, and lodging outlets face layered state and local licensing, food-code, alcohol, and tort obligations. Students learn to translate regulatory duties into preventive controls and defensible records.', 5),
  ('047cca9a-4e87-4f95-bbce-003556e9a419', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '3fa82243-5fa0-462c-a233-bb1fbfa95326', 'subtopic'::public.curated_course_node_type, 'Retail food regulation and active managerial control', 'Students learn how the FDA Food Code functions as a model and why the adopted state or local code and permit conditions control the operation.', 0),
  ('e58a4bb8-9683-4c38-919a-74daab13a26e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '047cca9a-4e87-4f95-bbce-003556e9a419', 'concept'::public.curated_course_node_type, 'Food establishment permits, inspections, grades, embargo, correction, closure, hearings, and appeals', null, 0),
  ('cc66cf36-5ae8-43ac-a81f-139430b6701b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '047cca9a-4e87-4f95-bbce-003556e9a419', 'concept'::public.curated_course_node_type, 'Person in charge, employee health, hygiene, time/temperature control, contamination, sanitation, HACCP, and variances', null, 1),
  ('6801fc20-68fa-4248-b453-382ad5f3ba81', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '047cca9a-4e87-4f95-bbce-003556e9a419', 'concept'::public.curated_course_node_type, 'Supplier approval, traceability, recalls, complaints, outbreak cooperation, logs, and corrective action', null, 2),
  ('9cf1cf7a-18cb-4bef-83ec-c4364c255904', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '3fa82243-5fa0-462c-a233-bb1fbfa95326', 'subtopic'::public.curated_course_node_type, 'Food allergens and consumer communication', 'This subtopic addresses the legal and operational consequences of inaccurate ingredient, menu, and service communication.', 1),
  ('17dfba8d-844c-4f3a-b0e1-b4738aa72265', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9cf1cf7a-18cb-4bef-83ec-c4364c255904', 'concept'::public.curated_course_node_type, 'Nine major allergens under federal packaged-food law; jurisdiction-specific restaurant requirements', null, 0),
  ('e6a2b4d2-70e7-4047-8b14-151693154e27', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9cf1cf7a-18cb-4bef-83ec-c4364c255904', 'concept'::public.curated_course_node_type, 'Written allergen notification under jurisdictions adopting relevant FDA Food Code provisions', null, 1),
  ('08a4e6f3-9009-4b9b-b269-62b8e0166144', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9cf1cf7a-18cb-4bef-83ec-c4364c255904', 'concept'::public.curated_course_node_type, 'Cross-contact prevention, recipe control, substitutions, server escalation, emergency response, and documentation', null, 2),
  ('32bbd449-13a0-4d8d-9b6a-7d3c5d4c8cb6', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '3fa82243-5fa0-462c-a233-bb1fbfa95326', 'subtopic'::public.curated_course_node_type, 'Alcohol licensing and liability', 'Students compare the three-tier system and state/local rules while recognizing that service, age, hours, promotions, and liability vary substantially by jurisdiction.', 2),
  ('8f2e97f6-96f1-4672-85f8-f71419e93b9e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '32bbd449-13a0-4d8d-9b6a-7d3c5d4c8cb6', 'concept'::public.curated_course_node_type, 'Licenses, permits, tied-house and supplier issues, hours, age verification, records, and enforcement', null, 0),
  ('1e2aed1a-9a6c-4181-9b12-2474a2617986', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '32bbd449-13a0-4d8d-9b6a-7d3c5d4c8cb6', 'concept'::public.curated_course_node_type, 'Responsible service, intoxication, underage service, promotions, delivery, cannabis interactions, and refusal', null, 1),
  ('cb1bceb3-f1a6-412f-ae01-11191c1c1862', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '32bbd449-13a0-4d8d-9b6a-7d3c5d4c8cb6', 'concept'::public.curated_course_node_type, 'Dram-shop and social-host liability, causation, safe transportation, incident reporting, and insurance', null, 2),
  ('6ff36760-bd3b-410d-b2d8-cabc181e62ed', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Employment, Wage-and-Hour, Labor, and Immigration Compliance', 'Hospitality''s round-the-clock, tipped, multilingual, seasonal, and franchise-based workforce creates distinctive legal risk. This section helps future managers apply fair, documented practices and recognize when federal, state, local, union, or immigration rules require specialist support.', 6),
  ('ca731f04-99e0-41f5-9d03-3de4dd68df79', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '6ff36760-bd3b-410d-b2d8-cabc181e62ed', 'subtopic'::public.curated_course_node_type, 'Wage-and-hour and scheduling', 'Students examine the records and classification decisions behind wages, tips, overtime, deductions, meals, uniforms, and working time.', 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('6014f98e-04df-49f6-a0c6-3c709adbbbf1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'ca731f04-99e0-41f5-9d03-3de4dd68df79', 'concept'::public.curated_course_node_type, 'FLSA coverage, employee versus contractor, exempt versus nonexempt, hours worked, regular rate, overtime, and records', null, 0),
