  ('4c2fcb7a-a3e6-4bd1-b4d2-82ba42f6f2b5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '83354034-6257-4892-aa44-3a3b3c0fae22', 'concept'::public.curated_course_node_type, 'Title VII, ADA, ADEA, Equal Pay Act, GINA, Pregnancy Workers Fairness Act, and state/local protections', null, 0),
  ('6e31849c-da28-431f-bd17-48bb196b3531', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '83354034-6257-4892-aa44-3a3b3c0fae22', 'concept'::public.curated_course_node_type, 'Disability, religion, pregnancy, lactation, interactive process, undue hardship, confidentiality, and retaliation', null, 1),
  ('a035349a-9ba1-426a-b40f-1aa341f1584f', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '83354034-6257-4892-aa44-3a3b3c0fae22', 'concept'::public.curated_course_node_type, 'Harassment by supervisors, coworkers, guests, vendors, and digital channels; reporting, investigation, and corrective action', null, 2),
  ('832c2251-4f00-4b1a-a932-8cc31401b731', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '6ff36760-bd3b-410d-b2d8-cabc181e62ed', 'subtopic'::public.curated_course_node_type, 'Labor relations, leave, safety, and work authorization', 'Students learn the overlapping rights that affect employee voice, injury prevention, leave, organizing, and verification.', 2),
  ('c6446d4c-2ae8-40e5-9c89-caf2f7cb077b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '832c2251-4f00-4b1a-a932-8cc31401b731', 'concept'::public.curated_course_node_type, 'NLRA protected concerted activity, wage discussions, organizing, supervisors, union rules, bargaining, and discipline', null, 0),
  ('af0adace-7ab5-4d6c-8fc2-069c7bff6b10', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '832c2251-4f00-4b1a-a932-8cc31401b731', 'concept'::public.curated_course_node_type, 'OSHA duties, hazard communication, injury records, workers'' compensation, FMLA, USERRA, and state leave laws', null, 1),
  ('0353ae7c-eca1-49e8-a266-d29e400b9477', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '832c2251-4f00-4b1a-a932-8cc31401b731', 'concept'::public.curated_course_node_type, 'Form I-9, nondiscriminatory verification, E-Verify where applicable, visas, minors, trafficking risks, and document retention', null, 2),
  ('4e02811c-dbb9-42cc-b27d-9aab10d09df5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Accessibility and Civil Rights in Guest Service', 'American hospitality is a public-accommodation setting. Students learn to design equal access across reservations, facilities, transportation, digital channels, communication, policies, and emergency procedures—not merely react to complaints.', 7),
  ('fa9b3d53-eabe-4ca6-909d-50b3b5a0cab1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e02811c-dbb9-42cc-b27d-9aab10d09df5', 'subtopic'::public.curated_course_node_type, 'ADA Title III service obligations', 'Students apply the concepts of equal enjoyment, reasonable policy modification, effective communication, and barrier removal to real hospitality interactions.', 0),
  ('6f1cc06a-451e-43e5-a863-4bf8a616ac6d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'fa9b3d53-eabe-4ca6-909d-50b3b5a0cab1', 'concept'::public.curated_course_node_type, 'Public accommodations, eligibility criteria, surcharges, direct threat, fundamental alteration, and undue burden', null, 0),
  ('952ed21b-95a2-4796-9ce5-824deb01f04e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'fa9b3d53-eabe-4ca6-909d-50b3b5a0cab1', 'concept'::public.curated_course_node_type, 'Service animals, mobility devices, auxiliary aids, interpreters, captioning, accessible formats, and companions', null, 1),
  ('449f907b-f6ff-4406-b25a-c1372bccaa13', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'fa9b3d53-eabe-4ca6-909d-50b3b5a0cab1', 'concept'::public.curated_course_node_type, 'Reservation staff knowledge, accessible-room information, room holds, equivalent options, and training', null, 2),
  ('cb7ee80f-1274-4098-b8f4-f15bfcf1b976', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e02811c-dbb9-42cc-b27d-9aab10d09df5', 'subtopic'::public.curated_course_node_type, 'Facilities, alterations, and operational access', 'This subtopic links design standards with daily practices that keep accessible features usable.', 1),
  ('980df0ba-90b5-4d83-aafa-c37afbdd16a8', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'cb7ee80f-1274-4098-b8f4-f15bfcf1b976', 'concept'::public.curated_course_node_type, '2010 ADA Standards, new construction, alterations, path of travel, barrier removal, and readily achievable analysis', null, 0),
  ('f899dd81-07c9-4242-955b-d1629eb618b5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'cb7ee80f-1274-4098-b8f4-f15bfcf1b976', 'concept'::public.curated_course_node_type, 'Entrances, parking, counters, guest rooms, bathrooms, pools, restaurants, meeting rooms, fitness, transportation, and evacuation', null, 1),
  ('2801f129-856c-46d3-900e-a275f17c0592', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'cb7ee80f-1274-4098-b8f4-f15bfcf1b976', 'concept'::public.curated_course_node_type, 'Maintenance of accessible features, temporary barriers, furniture, snow, outages, inspections, and remediation', null, 2),
  ('aca43de3-99be-45f6-be02-7cd5247ed980', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e02811c-dbb9-42cc-b27d-9aab10d09df5', 'subtopic'::public.curated_course_node_type, 'Digital access and broader civil-rights duties', 'Students examine websites, apps, kiosks, and the interaction of federal law with state and local public-accommodation protections.', 2),
  ('852e46e3-c565-4be2-a91c-bbbd9fbb3aff', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'aca43de3-99be-45f6-be02-7cd5247ed980', 'concept'::public.curated_course_node_type, 'Booking, menus, check-in, digital keys, loyalty, employment portals, documents, and effective alternatives', null, 0),
  ('a3fe1bd4-3a54-4129-97fc-7132f4832dbf', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'aca43de3-99be-45f6-be02-7cd5247ed980', 'concept'::public.curated_course_node_type, 'DOJ web-accessibility guidance, WCAG as a technical reference, procurement, testing, complaints, and remediation', null, 1),
  ('5e14bb65-1eb8-4684-89ae-d7f0a11cf077', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'aca43de3-99be-45f6-be02-7cd5247ed980', 'concept'::public.curated_course_node_type, 'Race, color, religion, national origin, sex, sexual orientation, gender identity, disability, and other state/local protected classes', null, 2),
  ('4656b6b5-1367-43ed-8b30-3b1b2d6e494c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Ownership, Franchising, Management Agreements, and Real Estate', 'Hospitality assets often separate ownership, brand, operation, employment, real estate, and intellectual property. This section helps students identify who controls which decision and where obligations, fees, standards, and liability reside.', 8),
  ('4e63b7fc-61fb-4368-ac7c-f39e2729828c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4656b6b5-1367-43ed-8b30-3b1b2d6e494c', 'subtopic'::public.curated_course_node_type, 'Entity, ownership, and authority structures', 'Students map legal entities and decision rights before attributing a promise, duty, asset, employee, or claim to the wrong party.', 0),
  ('59567bdb-d64a-41f0-a108-9459424b5daf', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e63b7fc-61fb-4368-ac7c-f39e2729828c', 'concept'::public.curated_course_node_type, 'Corporations, limited liability companies, partnerships, joint ventures, owners, operators, brands, and asset managers', null, 0),
  ('5cc0b336-b258-4909-acfa-df364952cb47', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e63b7fc-61fb-4368-ac7c-f39e2729828c', 'concept'::public.curated_course_node_type, 'Governing documents, fiduciary duties, authority matrices, guarantees, indemnities, and intercompany agreements', null, 1),
  ('9690d7d1-b8b2-4067-9bb0-ba3707c333e6', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e63b7fc-61fb-4368-ac7c-f39e2729828c', 'concept'::public.curated_course_node_type, 'Bankruptcy, receivership, lender rights, change of control, due diligence, and successor exposure', null, 2),
  ('2ea33f7c-f1be-48ee-973e-fa9c2692c00f', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4656b6b5-1367-43ed-8b30-3b1b2d6e494c', 'subtopic'::public.curated_course_node_type, 'Franchise relationships', 'This subtopic introduces federal disclosure rules and the contract and state-law issues that shape hotel and restaurant franchises.', 1),
  ('e267a8a9-a871-41c7-b163-e5d2b0feb421', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ea33f7c-f1be-48ee-973e-fa9c2692c00f', 'concept'::public.curated_course_node_type, 'FTC Franchise Rule, Franchise Disclosure Document, 23 disclosure items, timing, and earnings claims', null, 0),
  ('a13d6835-e72c-4675-8810-22588f5b577a', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ea33f7c-f1be-48ee-973e-fa9c2692c00f', 'concept'::public.curated_course_node_type, 'Brand standards, fees, reservations, loyalty, procurement, technology, territory, quality assurance, defaults, cure, and termination', null, 1),
  ('67ba5c9b-580f-44ac-b687-0ff520a90a39', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ea33f7c-f1be-48ee-973e-fa9c2692c00f', 'concept'::public.curated_course_node_type, 'State registration and relationship laws, encroachment, good faith, vicarious liability, and joint-employer concerns', null, 2),
  ('9fe1925a-de78-4232-bf84-117b6176eca5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4656b6b5-1367-43ed-8b30-3b1b2d6e494c', 'subtopic'::public.curated_course_node_type, 'Hotel management and property agreements', 'Students compare management contracts and real-estate arrangements that determine control, economics, standards, and exit rights.', 2),
  ('ede4fbc7-bde5-4445-8a46-614c525400c8', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9fe1925a-de78-4232-bf84-117b6176eca5', 'concept'::public.curated_course_node_type, 'Owner/operator roles, term, base and incentive fees, budget, personnel, accounts, procurement, and performance tests', null, 0),
  ('010301a9-66c6-4e08-be64-e790d184836c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9fe1925a-de78-4232-bf84-117b6176eca5', 'concept'::public.curated_course_node_type, 'Licenses, leases, easements, zoning, permits, land use, environmental conditions, and nuisance', null, 1),
  ('3a781cc6-a334-4771-81f6-5811654f4deb', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '9fe1925a-de78-4232-bf84-117b6176eca5', 'concept'::public.curated_course_node_type, 'Capital plans, insurance, indemnity, condemnation, casualty, force majeure, termination, and transition', null, 2),
  ('a2a659df-7e31-4fce-afa6-929a99b6bd91', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Consumer Protection, Marketing, Pricing, and Intellectual Property', 'Hospitality representations appear in rates, fees, menus, reviews, loyalty terms, photos, music, events, and influencer content. Students learn to assess what a reasonable consumer is likely to understand and whether the business can substantiate its claims and rights.', 9),
  ('7f921f53-d792-448e-b746-b44b59a6642e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a2a659df-7e31-4fce-afa6-929a99b6bd91', 'subtopic'::public.curated_course_node_type, 'Pricing, fees, promotions, and unfair practices', 'Students connect the FTC Act, the federal rule on unfair or deceptive fees, and state consumer-protection law to the guest purchase journey.', 0),
  ('c5c457b7-f09d-45a6-be59-359ba15bd616', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7f921f53-d792-448e-b746-b44b59a6642e', 'concept'::public.curated_course_node_type, 'Total price disclosure for covered short-term lodging, mandatory fees, optional add-ons, taxes, clear and conspicuous presentation', null, 0);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('9f49a848-91ae-437d-8a4f-b2893cbc2615', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7f921f53-d792-448e-b746-b44b59a6642e', 'concept'::public.curated_course_node_type, 'Coupons, packages, deposits, refunds, cancellation, scarcity claims, loyalty prices, gift cards, and automatic renewal', null, 1),
  ('091d2669-dedb-4e4e-a090-e53817d69da1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7f921f53-d792-448e-b746-b44b59a6642e', 'concept'::public.curated_course_node_type, 'Unfair or deceptive acts, state UDAP laws, attorney-general enforcement, private claims, class actions, and records', null, 2),
  ('23f41b5f-aa0c-4c11-9666-ac560b397a2e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a2a659df-7e31-4fce-afa6-929a99b6bd91', 'subtopic'::public.curated_course_node_type, 'Advertising, reviews, and endorsements', 'This subtopic focuses on truthful claims, material connections, review integrity, and consistency across direct and intermediary channels.', 1),
  ('ab66e8d2-a7bb-4886-a34c-f1a7fbcd2227', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '23f41b5f-aa0c-4c11-9666-ac560b397a2e', 'concept'::public.curated_course_node_type, 'Claim substantiation, disclosures, photos, amenities, accessibility, sustainability, health, safety, and comparative claims', null, 0),
  ('a3c5b487-7b0c-4af2-b965-0a3f6c9cbb5c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '23f41b5f-aa0c-4c11-9666-ac560b397a2e', 'concept'::public.curated_course_node_type, 'Influencers, employees, affiliates, travel advisors, native advertising, endorsements, and material connections', null, 1),
  ('a072d141-2a52-4a3d-94c2-2b9278044d53', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '23f41b5f-aa0c-4c11-9666-ac560b397a2e', 'concept'::public.curated_course_node_type, 'Consumer reviews, fake reviews, suppression, incentives, platform terms, reputation management, and defamation risk', null, 2),
  ('bedba8c0-dd76-44b9-a82d-3783adcc1837', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a2a659df-7e31-4fce-afa6-929a99b6bd91', 'subtopic'::public.curated_course_node_type, 'Intellectual property and publicity', 'Students identify the permissions needed to use brands, creative works, performances, guest images, and event content.', 2),
  ('0ca3f8e9-6776-4423-9dea-ace30c0920c6', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bedba8c0-dd76-44b9-a82d-3783adcc1837', 'concept'::public.curated_course_node_type, 'Trademarks, trade dress, domain names, licenses, franchised marks, quality control, and infringement', null, 0),
  ('4c3b9aac-7697-4331-befc-6aebaefe8d2e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bedba8c0-dd76-44b9-a82d-3783adcc1837', 'concept'::public.curated_course_node_type, 'Copyright in photos, menus, websites, software, music, video, décor, training, and user-generated content', null, 1),
  ('16e407b8-de15-43b8-aa9d-64f3268f86ab', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'bedba8c0-dd76-44b9-a82d-3783adcc1837', 'concept'::public.curated_course_node_type, 'Patents, trade secrets, confidentiality, employee work, rights of publicity, releases, and takedowns', null, 2),
  ('7ab33aaa-3d8d-498f-926b-5e188a270132', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Privacy, Data Security, Surveillance, and Technology Law', 'Hospitality businesses collect identity, payment, location, preference, loyalty, employment, and sometimes biometric data. Students learn to map the data life cycle, honor representations, reduce unnecessary collection, and prepare for incidents across a patchwork of U.S. laws.', 10),
  ('2ef4cd43-5c5d-41f7-90b0-efb88cac6fab', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7ab33aaa-3d8d-498f-926b-5e188a270132', 'subtopic'::public.curated_course_node_type, 'Privacy governance and consumer rights', 'Students examine what data is collected, why, under which notice or permission, and which jurisdiction or contract governs it.', 0),
  ('35b0a4a9-ec19-4468-b658-6a1a9ab6d44d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ef4cd43-5c5d-41f7-90b0-efb88cac6fab', 'concept'::public.curated_course_node_type, 'Data inventory, classification, purpose, minimization, notice, consent, access, correction, deletion, retention, disposal, and accountability', null, 0),
  ('7768125b-89dd-4a78-985f-7cf1295fd2d7', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ef4cd43-5c5d-41f7-90b0-efb88cac6fab', 'concept'::public.curated_course_node_type, 'State comprehensive privacy laws, biometric and facial-recognition laws, children''s data, marketing communications, cookies, and location', null, 1),
  ('2005714d-98f1-425d-b5e6-e6f59650ef1c', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '2ef4cd43-5c5d-41f7-90b0-efb88cac6fab', 'concept'::public.curated_course_node_type, 'Service providers, data sales/sharing, cross-border transfers, loyalty programs, sensitive data, and dark patterns', null, 2),
  ('4e411651-7907-4e18-af6c-3d5a70523fd7', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7ab33aaa-3d8d-498f-926b-5e188a270132', 'subtopic'::public.curated_course_node_type, 'Reasonable security and vendor risk', 'This subtopic translates legal expectations and contractual duties into governance and operational safeguards.', 1),
  ('9180786d-0431-4340-ab8b-0153567ecc91', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e411651-7907-4e18-af6c-3d5a70523fd7', 'concept'::public.curated_course_node_type, 'FTC Act, state security statutes, PCI DSS as a contractual standard, incident representations, and industry practice', null, 0),
  ('ab67c825-d5a0-469c-9843-4f6e95f085a9', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e411651-7907-4e18-af6c-3d5a70523fd7', 'concept'::public.curated_course_node_type, 'Access control, multifactor authentication, encryption, patching, logging, backups, physical security, training, and testing', null, 1),
  ('bcee648b-f1d0-44d1-8e40-a283f57433b9', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '4e411651-7907-4e18-af6c-3d5a70523fd7', 'concept'::public.curated_course_node_type, 'Cloud, PMS/POS, franchise, platform, payment, Wi-Fi, IoT, vendor diligence, security clauses, audit, and termination', null, 2),
  ('0231897d-50b8-4e9c-b9d3-009dad50f1f3', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '7ab33aaa-3d8d-498f-926b-5e188a270132', 'subtopic'::public.curated_course_node_type, 'Surveillance, incident response, and breach notice', 'Students balance safety and analytics with privacy, labor, discrimination, and evidence concerns.', 2),
  ('a51e4c08-22dd-43fc-89e6-0ad19102b493', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0231897d-50b8-4e9c-b9d3-009dad50f1f3', 'concept'::public.curated_course_node_type, 'Cameras, audio, key logs, Wi-Fi analytics, location, biometrics, employee monitoring, notices, and restricted areas', null, 0),
  ('8f17f9d5-0b45-4d20-9760-e67b9d3c1848', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0231897d-50b8-4e9c-b9d3-009dad50f1f3', 'concept'::public.curated_course_node_type, 'Incident triage, containment, privilege, forensics, insurer, law enforcement, regulators, payment brands, and communications', null, 1),
  ('bb0deaa9-01ca-4ca5-bd24-515462eb7f1b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0231897d-50b8-4e9c-b9d3-009dad50f1f3', 'concept'::public.curated_course_node_type, 'State breach-notification triggers, timing, affected individuals, content, regulator/consumer-reporting notices, remediation, and lessons', null, 2),
  ('dcb40b03-3abb-47f8-ac6d-52f37475c651', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Risk Management, Insurance, Indemnity, and Claims', 'Legal risk cannot be eliminated, but it can be allocated, financed, monitored, and reduced. This section connects contracts and insurance with operational controls, reporting discipline, and fair treatment of injured or affected people.', 11),
  ('0889a7ed-73ff-4ce3-8706-baed82076977', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'dcb40b03-3abb-47f8-ac6d-52f37475c651', 'subtopic'::public.curated_course_node_type, 'Enterprise and operational risk assessment', 'Students use a repeatable process to identify hazards, affected parties, controls, owners, evidence, and residual risk.', 0),
  ('5b2ff728-c097-40c8-a49f-230f576fa662', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0889a7ed-73ff-4ce3-8706-baed82076977', 'concept'::public.curated_course_node_type, 'Risk registers, frequency, severity, velocity, aggregation, emerging risk, and risk appetite', null, 0),
  ('5895fc53-4f1c-4064-801b-e787e99324e5', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0889a7ed-73ff-4ce3-8706-baed82076977', 'concept'::public.curated_course_node_type, 'Avoid, reduce, transfer, finance, accept, monitor, and escalate', null, 1),
  ('7e6a1816-2d49-4726-9805-b9a6463ce63b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '0889a7ed-73ff-4ce3-8706-baed82076977', 'concept'::public.curated_course_node_type, 'Policies, training, inspections, maintenance, audits, complaints, near misses, corrective action, and board reporting', null, 2),
  ('d86d0cef-b507-48f5-aee2-5540425cea92', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'dcb40b03-3abb-47f8-ac6d-52f37475c651', 'subtopic'::public.curated_course_node_type, 'Insurance and contractual allocation', 'This subtopic helps managers recognize common coverage structures and contract language requiring broker or counsel review.', 1),
  ('09c260b5-e6ec-43f2-8f95-924351a706a1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd86d0cef-b507-48f5-aee2-5540425cea92', 'concept'::public.curated_course_node_type, 'Commercial general liability, property, business interruption, cyber, crime, auto, liquor, employment practices, workers'' compensation, and umbrella', null, 0),
  ('235ef4e8-ed3f-43db-b805-e3ac0ff41b09', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd86d0cef-b507-48f5-aee2-5540425cea92', 'concept'::public.curated_course_node_type, 'Named insured, additional insured, occurrence, claims-made, limits, retentions, deductibles, exclusions, endorsements, and certificates', null, 1),
  ('25f6b966-4ab8-4b8f-b0b8-6422a3018e26', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd86d0cef-b507-48f5-aee2-5540425cea92', 'concept'::public.curated_course_node_type, 'Indemnity, defense, limitation of liability, waiver of subrogation, insurance requirements, and anti-indemnity variation', null, 2),
  ('b8a6fb4e-100d-496d-b72e-ff4b983b639d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'dcb40b03-3abb-47f8-ac6d-52f37475c651', 'subtopic'::public.curated_course_node_type, 'Incident, claim, and litigation readiness', 'Students practice a compassionate and evidence-preserving response that avoids admissions, retaliation, spoliation, and late notice.', 2),
  ('1c81d629-36a9-45c2-b4f9-04500f94f72d', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b8a6fb4e-100d-496d-b72e-ff4b983b639d', 'concept'::public.curated_course_node_type, 'Immediate care, scene safety, photographs, witnesses, video retention, products, logs, and chain of custody', null, 0),
  ('54bf3d4e-6804-44e8-b433-1a2d14397838', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b8a6fb4e-100d-496d-b72e-ff4b983b639d', 'concept'::public.curated_course_node_type, 'Incident reports, privilege, insurer notice, reservation of rights, adjusters, experts, subpoenas, and litigation holds', null, 1),
  ('74977cf2-6c08-489d-ac4e-9a76605ae372', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'b8a6fb4e-100d-496d-b72e-ff4b983b639d', 'concept'::public.curated_course_node_type, 'Root-cause analysis, remedial measures, regulator cooperation, settlement authority, and lessons learned', null, 2),
  ('a4eb286f-37d7-4b41-bc12-2389acbd0930', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Compliance Programs, Ethics, Investigations, and Governance', 'A policy manual alone is not a compliance system. Students learn to build governance that assigns ownership, makes reporting safe, verifies controls, corrects problems, and connects legal duties with hospitality ethics and stakeholder trust.', 12),
  ('d0206957-9fbe-4cf3-a5f2-4deed9faf804', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a4eb286f-37d7-4b41-bc12-2389acbd0930', 'subtopic'::public.curated_course_node_type, 'Compliance program design', 'Students convert a legal inventory into practical controls and assurance activities suited to a property or enterprise.', 0),
  ('51f61eac-077c-49f5-ad28-185570c252e0', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd0206957-9fbe-4cf3-a5f2-4deed9faf804', 'concept'::public.curated_course_node_type, 'Risk assessment, obligations register, policies, standards, procedures, controls, owners, and evidence', null, 0),
  ('1251f8f3-af23-4831-b827-85ad1d8560a1', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd0206957-9fbe-4cf3-a5f2-4deed9faf804', 'concept'::public.curated_course_node_type, 'Training, communications, certifications, monitoring, testing, audits, hotline, and third-party management', null, 1);
insert into public.curated_course_nodes (id, course_id, parent_id, node_type, title, description, sort_order)
values
  ('564a4fa2-7df6-4b30-bde3-bf6b9cead052', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'd0206957-9fbe-4cf3-a5f2-4deed9faf804', 'concept'::public.curated_course_node_type, 'Metrics, exceptions, remediation, discipline, incentives, reporting, and continuous improvement', null, 2),
  ('42db401a-87c4-4f19-98b1-75a59b083238', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a4eb286f-37d7-4b41-bc12-2389acbd0930', 'subtopic'::public.curated_course_node_type, 'Complaints and workplace investigations', 'This subtopic emphasizes fair, prompt, confidential-to-the-extent-possible processes that protect evidence and prohibit retaliation.', 1),
  ('5dad091a-c08b-4b4b-842a-0c67f9c173f8', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '42db401a-87c4-4f19-98b1-75a59b083238', 'concept'::public.curated_course_node_type, 'Intake, triage, conflicts, interim measures, scope, plan, witnesses, documents, interviews, and credibility', null, 0),
  ('c32363c5-715c-43d9-b231-badda3d640f7', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '42db401a-87c4-4f19-98b1-75a59b083238', 'concept'::public.curated_course_node_type, 'Need-to-know confidentiality, privilege decisions, trauma-informed practice, accommodations, translation, and records', null, 1),
  ('09b39104-7bcb-48ce-a89d-df39f794355e', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '42db401a-87c4-4f19-98b1-75a59b083238', 'concept'::public.curated_course_node_type, 'Findings, standard of proof, corrective action, communication, anti-retaliation monitoring, and appeal or review', null, 2),
  ('557128d3-528d-4e98-8c48-200d044e5c19', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'a4eb286f-37d7-4b41-bc12-2389acbd0930', 'subtopic'::public.curated_course_node_type, 'Ethical judgment and governance', 'Students analyze what responsible hospitality leadership requires when legal minimums, commercial pressure, and stakeholder interests diverge.', 2),
  ('989c0aca-e7ff-43b9-893f-c1601dd1820b', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '557128d3-528d-4e98-8c48-200d044e5c19', 'concept'::public.curated_course_node_type, 'Conflicts of interest, gifts, bribery, procurement integrity, accurate books, whistleblowing, and board oversight', null, 0),
  ('8c9ec961-ff43-447c-ae65-c6717fea0ec2', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '557128d3-528d-4e98-8c48-200d044e5c19', 'concept'::public.curated_course_node_type, 'Guest dignity, worker voice, vulnerable people, environmental impacts, community relations, and human rights', null, 1),
  ('6c58dc44-ae32-45c1-a033-3d5a50adea60', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', '557128d3-528d-4e98-8c48-200d044e5c19', 'concept'::public.curated_course_node_type, 'Ethical frameworks, stakeholder mapping, escalation, dissent, documentation, accountability, and learning culture', null, 2),
  ('c1aba699-f1de-435e-90cb-674388050c83', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', null, 'topic'::public.curated_course_node_type, 'Legal Research, Case Briefing, Dispute Resolution, and Advocacy', 'The course culminates in the ability to read law carefully, separate rule from commentary, apply authority to facts, and communicate a defensible recommendation. Students also evaluate when negotiation, mediation, arbitration, agency process, or litigation best serves the organization and affected stakeholders.', 13),
  ('31d9b7e3-fae3-4c8a-bd08-7244b8e7aa6a', 'e0f1a2b3-4c5d-4e15-8f74-8a9b0c1d2e05', 'c1aba699-f1de-435e-90cb-674388050c83', 'subtopic'::public.curated_course_node_type, 'Research and authority validation', 'Students learn a reproducible method for finding current law and confirming that it applies to the relevant place, date, facts, and business.', 0),
